def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    if not alive_opponents:
        if hp <= 2 or no_water >= 1:
            return min(budget, 35)
        return min(budget, 18)

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_count += 1
        if opp.get('budget', 0) >= budget:
            rich_count += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)
            status = prev.get('status')
            if status in ('lost', 'failed', 'error'):
                desperate_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0
    if scarcity > 1:
        scarcity = 1

    base = 20 + 18 * scarcity

    if supply >= 22:
        base -= 4
    elif supply <= 17:
        base += 8

    if hp <= 2:
        base += 28
    elif hp <= 4:
        base += 12

    if no_water >= 2:
        base += 25
    elif no_water >= 1:
        base += 12

    if highest_prev > 0:
        if hp <= 3 or no_water >= 1:
            target = highest_prev + 2
            if target > base:
                base = target
        else:
            soft_target = avg_prev + 1
            if soft_target > base:
                base = soft_target

    if desperate_count >= max(1, len(alive_opponents) // 2):
        base += 6

    if rich_count >= max(1, len(alive_opponents) // 2) and hp > 3 and no_water == 0:
        base -= 4

    days_left = 10 - day + 1
    if days_left < 1:
        days_left = 1
    reserve_floor = 8 * days_left
    max_affordable = budget - reserve_floor
    if hp <= 3 or no_water >= 1:
        max_affordable = budget - 4 * days_left
    if max_affordable < 0:
        max_affordable = budget

    bid = base
    if bid > max_affordable:
        bid = max_affordable

    if hp <= 2 or no_water >= 2:
        emergency = min(budget, max(45, highest_prev + 3 if highest_prev > 0 else 45))
        if emergency > bid:
            bid = emergency

    if bid < 0:
        bid = 0
    if bid > budget:
        bid = budget

    return bid

def get_bid(day_context, my_status, opponents_status):
    supply = day_context['supply']
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    water_req = 8
    daily_salary = 140

    # If low health, bid high to secure water
    if hp <= 2:
        return min(budget, daily_salary * 0.95)
    # If moderate health, bid a fraction based on health
    elif hp <= 4:
        base = daily_salary * 0.65
    else:
        base = daily_salary * 0.4

    # Adjust based on supply scarcity
    if supply < 18:
